def run_powershell(code, timeout=None, ctx=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0046000" if __import__("os").path.isdir("./environment_mix/0046000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc_iso_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt_any(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo is None else s.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
                return dt
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            # tolerate common format we write
            try:
                return datetime.datetime.strptime(s, "%Y-%m-%dT%H:%M:%SZ")
            except Exception:
                return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)

        def b32(n, length):
            out = ""
            for _ in range(length):
                out = alphabet[n % 32] + out
                n //= 32
            return out

        rand = "".join(random.choice(alphabet) for _ in range(16))
        return f"{prefix}_{b32(ms,10)}{rand}"

    def _audit(endpoint, status, client_id=None, execution_id=None, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("psx_req"),
            "endpoint": endpoint,
            "status": status,
            "client_id": client_id,
            "execution_id": execution_id,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_utc_iso_z(),
        })
        _save("request_logs.json", logs)

    def _pick_client():
        clients = _load("clients.json")
        if not isinstance(clients, list):
            return None
        # choose an actually usable active client with sane config
        for c in clients:
            if not isinstance(c, dict):
                continue
            if c.get("status") != "active":
                continue
            dts = c.get("default_timeout_seconds")
            mts = c.get("max_timeout_seconds")
            rpm = c.get("requests_per_minute_limit")
            if not (isinstance(dts, int) and not isinstance(dts, bool)):  # bool is int subclass
                continue
            if not (isinstance(mts, int) and not isinstance(mts, bool)):
                continue
            if not (isinstance(rpm, int) and not isinstance(rpm, bool) and rpm >= 1):
                continue
            if not (1 <= dts <= 300 and 1 <= mts <= 300 and dts <= mts):
                continue
            return c
        # fallback any active client
        for c in clients:
            if isinstance(c, dict) and c.get("status") == "active":
                return c
        return None

    def _rate_limit_or_none(client):
        limit = client.get("requests_per_minute_limit")
        if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now_dt = datetime.datetime.utcnow()
        window_start = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client.get("id"):
                continue
            ts = _parse_dt_any(r.get("created_at"))
            if ts is None:
                continue
            if ts >= window_start:
                cnt += 1
        if cnt >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=limit)
        return None

    # --- validate inputs ---
    if not isinstance(code, str) or not code.strip():
        _audit("run_powershell", "error", None, None, "VALIDATION_ERROR", "code must be a non-empty string")
        return _err("VALIDATION_ERROR", "code must be a non-empty string")

    client = _pick_client()
    if not client:
        _audit("run_powershell", "error", None, None, "UNAUTHORIZED", "No active client available")
        return _err("UNAUTHORIZED", "No active client available for this operation")

    rl = _rate_limit_or_none(client)
    if rl:
        _audit("run_powershell", "error", client.get("id"), None, rl["error"]["code"], rl["error"]["message"])
        return rl

    # effective timeout: clamp [1,300], must not exceed client.max_timeout_seconds, default from client if None
    if timeout is None:
        timeout_eff = client.get("default_timeout_seconds")
    else:
        timeout_eff = timeout
    if not isinstance(timeout_eff, int) or isinstance(timeout_eff, bool):
        _audit("run_powershell", "error", client.get("id"), None, "VALIDATION_ERROR", "timeout must be an integer or null")
        return _err("VALIDATION_ERROR", "timeout must be an integer or null")
    timeout_eff = max(1, min(300, timeout_eff))
    max_t = client.get("max_timeout_seconds")
    if isinstance(max_t, int) and not isinstance(max_t, bool):
        if timeout_eff > max_t:
            timeout_eff = max_t
    else:
        # store inconsistent; still keep within [1,300]
        timeout_eff = max(1, min(300, timeout_eff))

    # --- persist execution request (no actual PS execution offline) ---
    executions = _load("powershell_executions.json")
    if not isinstance(executions, list):
        executions = []

    exec_id = _gen_id("psx_run")
    now = _now_utc_iso_z()
    row = {
        "id": exec_id,
        "client_id": client.get("id"),
        "request_id": getattr(ctx, "request_id", None) if ctx is not None else None,
        "tool_name": "run_powershell",
        "timeout_seconds": timeout_eff,
        "code": code,
        "arguments": None,
        "status": "succeeded",
        "started_at": now,
        "finished_at": now,
        "duration_ms": 0,
        "exit_code": 0,
        "stdout": "",
        "stderr": "",
        "combined_output": "",
        "error_type": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    executions.append(row)
    _save("powershell_executions.json", executions)

    _audit("run_powershell", "ok", client.get("id"), exec_id, None, None)
    return {"execution_id": exec_id, "output": row.get("combined_output") or ""}

