    executions = _load("powershell_executions.json")
    if not isinstance(executions, list):
        executions = []

    exec_id = _gen_id("psx_run")
    now = _now_utc_iso_z()
    args = {}
    if properties is not None:
        args["properties"] = properties

    row = {
        "id": exec_id,
        "client_id": client.get("id"),
        "request_id": None,
        "tool_name": "get_system_info",
        "timeout_seconds": timeout_eff,
        "code": None,
        "arguments": args if args else {},
        "status": "succeeded",
        "started_at": now,
        "finished_at": now,
        "duration_ms": 0,
        "exit_code": 0,
        "stdout": "",
        "stderr": "",
        "combined_output": "",
        "error_type": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    executions.append(row)
    _save("powershell_executions.json", executions)

    _audit("get_system_info", "ok", client.get("id"), exec_id, None, None)
    # return a deterministic minimal result set
    data = {
        "ComputerName": None,
        "OsName": None,
        "OsVersion": None,
    }
    if properties is None:
        return {"execution_id": exec_id, "system_info": data}
    filtered = {}
    for k in properties:
        # accept requested names even if unknown; return nulls (do not over-reject)
        filtered[k] = data.get(k)
    return {"execution_id": exec_id, "system_info": filtered}

