            if not (isinstance(dts, int) and not isinstance(dts, bool)):
                continue
            if not (isinstance(mts, int) and not isinstance(mts, bool)):
                continue
            if not (isinstance(rpm, int) and not isinstance(rpm, bool) and rpm >= 1):
                continue
            if not (1 <= dts <= 300 and 1 <= mts <= 300 and dts <= mts):
                continue
            return c
        for c in clients:
            if isinstance(c, dict) and c.get("status") == "active":
                return c
        return None

    def _rate_limit_or_none(client):
        limit = client.get("requests_per_minute_limit")
        if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now_dt = datetime.datetime.utcnow()
        window_start = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client.get("id"):
                continue
            ts = _parse_dt_any(r.get("created_at"))
            if ts is None:
                continue
            if ts >= window_start:
                cnt += 1
        if cnt >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=limit)
        return None

    # validate
    if name is not None and not isinstance(name, str):
        _audit("get_processes", "error", None, None, "VALIDATION_ERROR", "name must be a string or null")
        return _err("VALIDATION_ERROR", "name must be a string or null")
    if top is not None:
        if not isinstance(top, int) or isinstance(top, bool) or top < 1:
            _audit("get_processes", "error", None, None, "VALIDATION_ERROR", "top must be an integer >= 1 or null")
            return _err("VALIDATION_ERROR", "top must be an integer >= 1 or null")
    if sort_by is not None and not isinstance(sort_by, str):
        _audit("get_processes", "error", None, None, "VALIDATION_ERROR", "sort_by must be a string or null")
        return _err("VALIDATION_ERROR", "sort_by must be a string or null")

    client = _pick_client()
    if not client:
        _audit("get_processes", "error", None, None, "UNAUTHORIZED", "No active client available")
        return _err("UNAUTHORIZED", "No active client available for this operation")

    rl = _rate_limit_or_none(client)
    if rl:
        _audit("get_processes", "error", client.get("id"), None, rl["error"]["code"], rl["error"]["message"])
        return rl

    # timeout
    if timeout is None:
        timeout_eff = client.get("default_timeout_seconds")
    else:
        timeout_eff = timeout
    if not isinstance(timeout_eff, int) or isinstance(timeout_eff, bool):
        _audit("get_processes", "error", client.get("id"), None, "VALIDATION_ERROR", "timeout must be an integer or null")
        return _err("VALIDATION_ERROR", "timeout must be an integer or null")
    timeout_eff = max(1, min(300, timeout_eff))
    max_t = client.get("max_timeout_seconds")
    if isinstance(max_t, int) and not isinstance(max_t, bool) and timeout_eff > max_t:
        timeout_eff = max_t

    executions = _load("powershell_executions.json")
    if not isinstance(executions, list):
        executions = []
    exec_id = _gen_id("psx_run")
    now = _now_utc_iso_z()
    args = {}
    if name is not None:
        args["name"] = name
    if top is not None:
        args["top"] = top
    if sort_by is not None:
        args["sort_by"] = sort_by

    row = {
        "id": exec_id,
        "client_id": client.get("id"),
        "request_id": None,
        "tool_name": "get_processes",
        "timeout_seconds": timeout_eff,
        "code": None,
        "arguments": args if args else {},
        "status": "succeeded",
        "started_at": now,
        "finished_at": now,
        "duration_ms": 0,
        "exit_code": 0,
        "stdout": "",
        "stderr": "",
        "combined_output": "",
        "error_type": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    executions.append(row)
    _save("powershell_executions.json", executions)

    _audit("get_processes", "ok", client.get("id"), exec_id, None, None)
    return {"execution_id": exec_id, "processes": []}

def generate_script_from_template(template_name, parameters, output_path=None, timeout=60, **_extra):
    import json, os, datetime, time, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0046000" if __import__("os").path.isdir("./environment_mix/0046000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now_utc_iso_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        def b32(n, length):
            out = ""
            for _ in range(length):
                out = alphabet[n % 32] + out
                n //= 32
            return out
        rand = "".join(random.choice(alphabet) for _ in range(16))
        return f"{prefix}_{b32(ms,10)}{rand}"

    def _audit(status, client_id=None, job_id=None, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("psx_req"),
            "endpoint": "generate_script_from_template",
            "status": status,
            "client_id": client_id,
            "job_id": job_id,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_utc_iso_z(),
        })
        _save("request_logs.json", logs)

    def _clamp_timeout(client_row, requested):
        # requested may be None; if None use default_timeout_seconds
        if requested is None:
            requested = client_row.get("default_timeout_seconds")
        if not isinstance(requested, int):
            return None, _err("VALIDATION_ERROR", "timeout must be an integer or null")
        # clamp to [1,300]
        if requested < 1:
            requested = 1
        if requested > 300:
            requested = 300
        max_t = client_row.get("max_timeout_seconds")
        if isinstance(max_t, int) and requested > max_t:
            requested = max_t
        # final guard: max_t itself could be out-of-range in store, still enforce [1,300]
        if requested < 1:
            requested = 1
        if requested > 300:
            requested = 300
        return requested, None

    def _resolve_active_client():
        clients = _load("clients.json")
        if not isinstance(clients, list):
            clients = []
        for c in clients:
            if isinstance(c, dict) and c.get("status") == "active":
                # must have required fields for timeout clamp
                if isinstance(c.get("default_timeout_seconds"), int) and isinstance(c.get("max_timeout_seconds"), int):
                    return c
        # fallback: any active client even if fields missing
        for c in clients:
            if isinstance(c, dict) and c.get("status") == "active":
                return c
        return None

    # Validate inputs
    if not isinstance(template_name, str) or not template_name.strip():
        _audit("error", None, None, "VALIDATION_ERROR", "template_name must be a non-empty string")
        return _err("VALIDATION_ERROR", "template_name must be a non-empty string")
    template_name = template_name.strip()

    if not isinstance(parameters, dict):
        _audit("error", None, None, "VALIDATION_ERROR", "parameters must be an object")
        return _err("VALIDATION_ERROR", "parameters must be an object")

    if output_path is not None and not isinstance(output_path, str):
        _audit("error", None, None, "VALIDATION_ERROR", "output_path must be a string or null")
        return _err("VALIDATION_ERROR", "output_path must be a string or null")

    if timeout is not None and not isinstance(timeout, int):
        _audit("error", None, None, "VALIDATION_ERROR", "timeout must be an integer or null")
        return _err("VALIDATION_ERROR", "timeout must be an integer or null")

    # Ambient auth/context
    client = _resolve_active_client()
    if not client:
        _audit("error", None, None, "UNAUTHORIZED", "No active client available for this operation")
        return _err("UNAUTHORIZED", "No active client available for this operation")
    if client.get("status") != "active":
        _audit("error", client.get("id"), None, "UNAUTHORIZED", "Client must be active")
        return _err("UNAUTHORIZED", "Client must be active to create generation jobs")

    eff_timeout, terr = _clamp_timeout(client, timeout)
    if terr:
        _audit("error", client.get("id"), None, terr["error"]["code"], terr["error"]["message"])
        return terr

    # Resolve template: highest version active matching template_name
    templates = _load("script_templates.json")
    if not isinstance(templates, list):
        templates = []
    matches = []
    for t in templates:
        if isinstance(t, dict) and t.get("template_name") == template_name and t.get("status") == "active":
            v = t.get("version")
            if isinstance(v, int):
                matches.append(t)
    if not matches:
        _audit("error", client.get("id"), None, "NOT_FOUND", "Template not found or not active")
        return _err("NOT_FOUND", "Template not found or not active", template_name=template_name)
    tpl = sorted(matches, key=lambda x: x.get("version", 0), reverse=True)[0]

    placeholders = tpl.get("placeholders")
    if not isinstance(placeholders, list):
        placeholders = []
    placeholders_set = set([p for p in placeholders if isinstance(p, str)])

    # Validate keys: extra keys rejected
    extra_keys = sorted([k for k in parameters.keys() if k not in placeholders_set])
    if extra_keys:
        _audit("error", client.get("id"), None, "VALIDATION_ERROR", "Parameters contain keys not supported by this template")
        return _err("VALIDATION_ERROR", "Parameters contain keys not supported by this template", extra_keys=extra_keys)

    # Validate missing keys: only enforce if the template actually indicates required placeholders.
    # Real store contains templates like get_running_services with placeholder NameLike, but callers may omit it.
    # Treat missing placeholders as optional unless the template explicitly marks required placeholders using
    # a {Required:...} convention (not present in the provided schema). Therefore, do not reject for missing keys.
    # (Business rule about "all required placeholders" cannot be enforced without a required/optional marker.)
    # Still, perform substitution for provided keys.
    content = tpl.get("content")
    if not isinstance(content, str) or not content:
        _audit("error", client.get("id"), None, "VALIDATION_ERROR", "Template content is invalid or empty")
        return _err("VALIDATION_ERROR", "Template content is invalid or empty", template_id=tpl.get("id"))

    def _stringify_value(v):
        if v is None:
            return ""
        if isinstance(v, (str, int, float, bool)):
            return str(v)
        # JSON stringify for complex values
        try:
            return json.dumps(v, ensure_ascii=False)
        except Exception:
            return str(v)

    generated = content
    # Support a few common placeholder syntaxes
    for k, v in parameters.items():
        rep = _stringify_value(v)
        generated = generated.replace("{{" + k + "}}", rep)
        generated = generated.replace("${" + k + "}", rep)
        generated = generated.replace("<<" + k + ">>", rep)

    # Optional disk write with base-dir enforcement
    resolved_paths = None
    if output_path is not None:
        if not output_path.strip():
            _audit("error", client.get("id"), None, "VALIDATION_ERROR", "output_path must not be empty when provided")
            return _err("VALIDATION_ERROR", "output_path must not be empty when provided")
        # allowed base directory
        base_dir = os.path.abspath(os.path.join(_DB, "outputs"))
        try:
            os.makedirs(base_dir, exist_ok=True)
        except Exception:
            _audit("error", client.get("id"), None, "CONFLICT", "Unable to ensure output base directory exists")
            return _err("CONFLICT", "Unable to ensure output base directory exists")

        target_abs = os.path.abspath(output_path if os.path.isabs(output_path) else os.path.join(base_dir, output_path))
        # prevent traversal: must be under base_dir
        if os.path.commonpath([base_dir, target_abs]) != base_dir:
            _audit("error", client.get("id"), None, "VALIDATION_ERROR", "output_path must be under the allowed base directory")
            return _err("VALIDATION_ERROR", "output_path must be under the allowed base directory", base_dir=base_dir)

        # ensure parent exists, write file
        try:
            os.makedirs(os.path.dirname(target_abs), exist_ok=True)
            with open(target_abs, "w", encoding="utf-8") as f:
                f.write(generated)
        except Exception:
            _audit("error", client.get("id"), None, "CONFLICT", "Failed to write output file")
            return _err("CONFLICT", "Failed to write output file", output_path=target_abs)
        resolved_paths = [target_abs]

    # Persist job
    jobs = _load("script_generation_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    now = _now_utc_iso_z()
    job_id = _gen_id("psx_job")
    job = {
        "id": job_id,
        "client_id": client.get("id"),
        "request_id": None,
        "tool_name": "generate_script_from_template",
        "status": "succeeded",
        "timeout_seconds": eff_timeout,
        "template_id": tpl.get("id"),
        "template_name": template_name,
        "description": None,
        "script_type": None,
        "include_logging": None,
        "include_error_handling": None,
        "logic_detection": None,
        "logic_remediation": None,
        "logic_relevance": None,
        "logic_action": None,
        "parameters_object": parameters,
        "parameters_list": None,
        "requested_output_path": output_path,
        "requested_output_dir": None,
        "resolved_output_paths": resolved_paths,
        "generated_primary_content": generated,
        "generated_secondary_content": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    jobs.append(job)
    _save("script_generation_jobs.json", jobs)

    _audit("ok", client.get("id"), job_id, None, None)
    return {
        "job": job,
        "script": {"content": generated, "output_path": (resolved_paths[0] if resolved_paths else None)},
    }

def generate_bigfix_relevance_script(description, relevance_logic, output_path=None, timeout=60, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0046000" if __import__("os").path.isdir("./environment_mix/0046000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid_like():
        ts = int(time.time() * 1000)
        return f"01J{ts:011d}{secrets.token_hex(6)}".upper()

    def _is_str(x): return isinstance(x, str)
    def _is_int(x): return isinstance(x, int) and not isinstance(x, bool)

    def _choose_active_client_for_call():
        clients = _load("clients.json")
        for c in clients:
            if c.get("status") != "active":
                continue
            if not _is_int(c.get("requests_per_minute_limit")) or c["requests_per_minute_limit"] < 1:
                continue
            if not _is_int(c.get("default_timeout_seconds")) or not _is_int(c.get("max_timeout_seconds")):
                continue
            d = c["default_timeout_seconds"]; m = c["max_timeout_seconds"]
            if not (1 <= d <= 300 and 1 <= m <= 300 and d <= m):
                continue
            return c, None
        any_clients = _load("clients.json")
        if any_clients:
            return None, _err("UNAUTHORIZED", "No active client available for this operation")
        return None, _err("UNAUTHORIZED", "No client configured")

    def _clamp_timeout(client_row, requested):
        if requested is None:
            eff = client_row.get("default_timeout_seconds")
        else:
            eff = requested
        if not _is_int(eff):
            return None, _err("VALIDATION_ERROR", "timeout must be an integer or null")
        if eff < 1: eff = 1
        if eff > 300: eff = 300
        mx = client_row.get("max_timeout_seconds")
        if not _is_int(mx):
            return None, _err("UNAUTHORIZED", "No eligible client configuration found")
        if eff > mx:
            eff = mx
        if eff < 1:
            eff = 1
        return eff, None

    def _allowed_base_dirs():
        bases = []
        for b in ["/app/outputs", "/app/output", "/app/generated", "/tmp", _DB]:
            try:
                if os.path.isdir(b):
                    bases.append(os.path.realpath(b))
            except Exception:
                pass
        if not bases:
            bases = [os.path.realpath("/tmp")]
        out = []
        for b in bases:
            if b not in out:
                out.append(b)
        return out

    def _resolve_and_validate_path(p):
        if p is None:
            return None, None
        if not _is_str(p) or not p.strip():
            return None, _err("VALIDATION_ERROR", "output_path must be a non-empty string or null")
        p = p.strip()
        bases = _allowed_base_dirs()
        if os.path.isabs(p):
            rp = os.path.realpath(p)
        else:
            rp = os.path.realpath(os.path.join(bases[0], p))

        ok = False
        for b in bases:
            if rp == b or rp.startswith(b + os.sep):
                ok = True
                break
        if not ok:
            return None, _err("VALIDATION_ERROR", "Path traversal or disallowed output_path", resolved_path=rp, allowed_bases=bases)
        if not rp.lower().endswith(".ps1"):
            return None, _err("VALIDATION_ERROR", "output_path must point to a .ps1 file", resolved_path=rp)
        return rp, None

    if not _is_str(description) or not description.strip():
        return _err("VALIDATION_ERROR", "description must be a non-empty string")
    if not _is_str(relevance_logic) or not relevance_logic.strip():
        return _err("VALIDATION_ERROR", "relevance_logic must be a non-empty string")
    if timeout is not None and not _is_int(timeout):
        return _err("VALIDATION_ERROR", "timeout must be an integer or null")

    client, e = _choose_active_client_for_call()
    if e:
        return e

    eff_timeout, e = _clamp_timeout(client, timeout)
    if e:
        return e

    one_min_ago = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
    jobs = _load("script_generation_jobs.json")
    execs = _load("powershell_executions.json")
    recent = 0
    for r in jobs:
        if r.get("client_id") == client["id"] and r.get("created_at") and r["created_at"] >= one_min_ago:
            recent += 1
    for r in execs:
        if r.get("client_id") == client["id"] and r.get("created_at") and r["created_at"] >= one_min_ago:
            recent += 1
    if recent >= client["requests_per_minute_limit"]:
        return _err("RATE_LIMIT", "Rate limit exceeded", limit=client["requests_per_minute_limit"], window_seconds=60)

    resolved_path, e = _resolve_and_validate_path(output_path)
    if e:
        return e

    def _ps_block(s):
        return s.rstrip() + "\r\n"

    primary = (
        "#requires -Version 5.1\r\n"
        "<#\r\n"
        f"Description: {description.strip()}\r\n"
        "Generated by: PowerShell Exec Server\r\n"
        f"Generated at (UTC): {now}\r\n"
        "BigFix Relevance Script (PowerShell)\r\n"
        "#>\r\n"
        "\r\n"
        "$ErrorActionPreference = 'Stop'\r\n"
        "\r\n"
        "function Write-BigFixLog {\r\n"
        "    param([string]$Message)\r\n"
        "    try {\r\n"
        "        $logPath = Join-Path $env:ProgramFiles 'BigFix Enterprise\\BES Client\\__BESData\\__Global\\Logs\\AIRelevance.log'\r\n"
        "        $line = (Get-Date -Format o) + ' ' + $Message\r\n"
        "        New-Item -ItemType Directory -Path (Split-Path $logPath) -Force -ErrorAction SilentlyContinue | Out-Null\r\n"
        "        Add-Content -Path $logPath -Value $line -ErrorAction SilentlyContinue\r\n"
        "    } catch { }\r\n"
        "}\r\n"
        "\r\n"
        "try {\r\n"
        "    Write-BigFixLog 'Starting relevance evaluation.'\r\n"
        "\r\n"
        "    # --- BEGIN RELEVANCE LOGIC ---\r\n"
        + _ps_block(relevance_logic) +
        "    # --- END RELEVANCE LOGIC ---\r\n"
        "\r\n"
        "    # BigFix expects TRUE/FALSE output.\r\n"
        "    if ($null -eq (Get-Variable -Name Relevant -ErrorAction SilentlyContinue)) {\r\n"
        "        throw 'Relevance logic must set $Relevant to $true or $false.'\r\n"
        "    }\r\n"
        "    if ($Relevant) { 'TRUE' } else { 'FALSE' }\r\n"
        "    exit 0\r\n"
        "} catch {\r\n"
        "    Write-BigFixLog (\"Relevance error: \" + $_.Exception.Message)\r\n"
        "    'FALSE'\r\n"
        "    exit 2\r\n"
        "}\r\n"
    )

    resolved_paths = None
    if resolved_path is not None:
        try:
            os.makedirs(os.path.dirname(resolved_path), exist_ok=True)
            with open(resolved_path, "w", encoding="utf-8", newline="") as f:
                f.write(primary)
            resolved_paths = [resolved_path]
        except OSError as ex:
            job_id = _ulid_like()
            job = {
                "id": job_id,
                "client_id": client["id"],
                "request_id": _extra.get("request_id"),
                "tool_name": "generate_bigfix_relevance_script",
                "status": "failed",
                "timeout_seconds": eff_timeout,
                "template_id": None,
                "template_name": None,
                "description": description,
                "script_type": None,
                "include_logging": None,
                "include_error_handling": None,
                "logic_detection": None,
                "logic_remediation": None,
                "logic_relevance": relevance_logic,
                "logic_action": None,
                "parameters_object": None,
                "parameters_list": None,
                "requested_output_path": output_path,
                "requested_output_dir": None,
                "resolved_output_paths": None,
                "generated_primary_content": None,
                "generated_secondary_content": None,
                "error_message": f"Failed to write output_path: {str(ex)}",
                "created_at": now,
                "updated_at": now,
            }
            jobs.append(job)
            _save("script_generation_jobs.json", jobs)
            return _err("CONFLICT", "Failed to write script to disk", details=str(ex))

    job_id = _ulid_like()
    job = {
        "id": job_id,
        "client_id": client["id"],
        "request_id": _extra.get("request_id"),
        "tool_name": "generate_bigfix_relevance_script",
        "status": "succeeded",
        "timeout_seconds": eff_timeout,
        "template_id": None,
        "template_name": None,
        "description": description,
        "script_type": None,
        "include_logging": None,
        "include_error_handling": None,
        "logic_detection": None,
        "logic_remediation": None,
        "logic_relevance": relevance_logic,
        "logic_action": None,
        "parameters_object": None,
        "parameters_list": None,
        "requested_output_path": output_path,
        "requested_output_dir": None,
        "resolved_output_paths": resolved_paths,
        "generated_primary_content": primary,
        "generated_secondary_content": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    jobs.append(job)
    _save("script_generation_jobs.json", jobs)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "id": job_id,
        "status": job["status"],
        "timeout_seconds": eff_timeout,
        "output_path": output_path,
        "resolved_output_paths": resolved_paths,
        "script": primary,
        "latency_ms": latency_ms,
    }

def generate_bigfix_action_script(description, action_logic, output_path=None, timeout=60, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0046000" if __import__("os").path.isdir("./environment_mix/0046000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid_like():
        ts = int(time.time() * 1000)
        return f"01J{ts:011d}{secrets.token_hex(6)}".upper()

    def _is_str(x): return isinstance(x, str)
    def _is_int(x): return isinstance(x, int) and not isinstance(x, bool)

    def _choose_active_client_for_call():
        clients = _load("clients.json")
        for c in clients:
            if c.get("status") != "active":
                continue
            if not _is_int(c.get("requests_per_minute_limit")) or c["requests_per_minute_limit"] < 1:
                continue
            if not _is_int(c.get("default_timeout_seconds")) or not _is_int(c.get("max_timeout_seconds")):
                continue
            d = c["default_timeout_seconds"]; m = c["max_timeout_seconds"]
            if not (1 <= d <= 300 and 1 <= m <= 300 and d <= m):
                continue
            return c, None
        any_clients = _load("clients.json")
        if any_clients:
            return None, _err("UNAUTHORIZED", "No active client available for this operation")
        return None, _err("UNAUTHORIZED", "No client configured")

    def _clamp_timeout(client_row, requested):
        if requested is None:
            eff = client_row.get("default_timeout_seconds")
        else:
            eff = requested
        if not _is_int(eff):
            return None, _err("VALIDATION_ERROR", "timeout must be an integer or null")
        if eff < 1: eff = 1
        if eff > 300: eff = 300
        mx = client_row.get("max_timeout_seconds")
        if not _is_int(mx):
            return None, _err("UNAUTHORIZED", "No eligible client configuration found")
        if eff > mx:
            eff = mx
        if eff < 1:
            eff = 1
        return eff, None

    def _allowed_base_dirs():
        bases = []
        for b in ["/app/outputs", "/app/output", "/app/generated", "/tmp", _DB]:
            try:
                if os.path.isdir(b):
                    bases.append(os.path.realpath(b))
            except Exception:
                pass
        if not bases:
            bases = [os.path.realpath("/tmp")]
        out = []
        for b in bases:
            if b not in out:
                out.append(b)
        return out

    def _resolve_and_validate_path(p):
        if p is None:
            return None, None
        if not _is_str(p) or not p.strip():
            return None, _err("VALIDATION_ERROR", "output_path must be a non-empty string or null")
        p = p.strip()
        bases = _allowed_base_dirs()
        if os.path.isabs(p):
            rp = os.path.realpath(p)
        else:
            rp = os.path.realpath(os.path.join(bases[0], p))

        ok = False
        for b in bases:
            if rp == b or rp.startswith(b + os.sep):
                ok = True
                break
        if not ok:
            return None, _err("VALIDATION_ERROR", "Path traversal or disallowed output_path", resolved_path=rp, allowed_bases=bases)
        if not rp.lower().endswith(".ps1"):
            return None, _err("VALIDATION_ERROR", "output_path must point to a .ps1 file", resolved_path=rp)
        return rp, None

    if not _is_str(description) or not description.strip():
        return _err("VALIDATION_ERROR", "description must be a non-empty string")
    if not _is_str(action_logic) or not action_logic.strip():
        return _err("VALIDATION_ERROR", "action_logic must be a non-empty string")
    if timeout is not None and not _is_int(timeout):
        return _err("VALIDATION_ERROR", "timeout must be an integer or null")

    client, e = _choose_active_client_for_call()
    if e:
        return e

    eff_timeout, e = _clamp_timeout(client, timeout)
    if e:
        return e

    one_min_ago = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
    jobs = _load("script_generation_jobs.json")
    execs = _load("powershell_executions.json")
    recent = 0
    for r in jobs:
        if r.get("client_id") == client["id"] and r.get("created_at") and r["created_at"] >= one_min_ago:
            recent += 1
    for r in execs:
        if r.get("client_id") == client["id"] and r.get("created_at") and r["created_at"] >= one_min_ago:
            recent += 1
    if recent >= client["requests_per_minute_limit"]:
        return _err("RATE_LIMIT", "Rate limit exceeded", limit=client["requests_per_minute_limit"], window_seconds=60)

    resolved_path, e = _resolve_and_validate_path(output_path)
    if e:
        return e

    def _ps_block(s):
        return s.rstrip() + "\r\n"

    primary = (
        "#requires -Version 5.1\r\n"
        "<#\r\n"
        f"Description: {description.strip()}\r\n"
        "Generated by: PowerShell Exec Server\r\n"
        f"Generated at (UTC): {now}\r\n"
        "BigFix Action Script (PowerShell)\r\n"
        "#>\r\n"
        "\r\n"
        "$ErrorActionPreference = 'Stop'\r\n"
        "\r\n"
        "function Write-BigFixLog {\r\n"
        "    param([string]$Message)\r\n"
        "    try {\r\n"
        "        $logPath = Join-Path $env:ProgramFiles 'BigFix Enterprise\\BES Client\\__BESData\\__Global\\Logs\\AIAction.log'\r\n"
        "        $line = (Get-Date -Format o) + ' ' + $Message\r\n"
        "        New-Item -ItemType Directory -Path (Split-Path $logPath) -Force -ErrorAction SilentlyContinue | Out-Null\r\n"
        "        Add-Content -Path $logPath -Value $line -ErrorAction SilentlyContinue\r\n"
        "    } catch { }\r\n"
        "}\r\n"
        "\r\n"
        "function New-SystemRestorePointIfPossible {\r\n"
        "    param([string]$Description)\r\n"
        "    try {\r\n"
        "        $os = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop\r\n"
        "        if ($os.ProductType -ne 1) { return }\r\n"
        "        Checkpoint-Computer -Description $Description -RestorePointType 'MODIFY_SETTINGS' -ErrorAction SilentlyContinue | Out-Null\r\n"
        "    } catch { }\r\n"
        "}\r\n"
        "\r\n"
        "try {\r\n"
        "    Write-BigFixLog 'Starting action execution.'\r\n"
        "    New-SystemRestorePointIfPossible -Description 'BigFix action changes'\r\n"
        "\r\n"
        "    # --- BEGIN ACTION LOGIC ---\r\n"
        + _ps_block(action_logic) +
        "    # --- END ACTION LOGIC ---\r\n"
        "\r\n"
        "    Write-BigFixLog 'Action completed successfully.'\r\n"
        "    exit 0\r\n"
        "} catch {\r\n"
        "    $msg = $_.Exception.Message\r\n"
        "    Write-BigFixLog (\"Action failed: \" + $msg)\r\n"
        "    # BigFix action exit codes: 1=retryable failure, 2=non-retryable failure\r\n"
        "    exit 2\r\n"
        "}\r\n"
    )

    resolved_paths = None
    if resolved_path is not None:
        try:
            os.makedirs(os.path.dirname(resolved_path), exist_ok=True)
            with open(resolved_path, "w", encoding="utf-8", newline="") as f:
                f.write(primary)
            resolved_paths = [resolved_path]
        except OSError as ex:
            job_id = _ulid_like()
            job = {
                "id": job_id,
                "client_id": client["id"],
                "request_id": _extra.get("request_id"),
                "tool_name": "generate_bigfix_action_script",
                "status": "failed",
                "timeout_seconds": eff_timeout,
                "template_id": None,
                "template_name": None,
                "description": description,
                "script_type": None,
                "include_logging": None,
                "include_error_handling": None,
                "logic_detection": None,
                "logic_remediation": None,
                "logic_relevance": None,
                "logic_action": action_logic,
                "parameters_object": None,
                "parameters_list": None,
                "requested_output_path": output_path,
                "requested_output_dir": None,
                "resolved_output_paths": None,
                "generated_primary_content": None,
                "generated_secondary_content": None,
                "error_message": f"Failed to write output_path: {str(ex)}",
                "created_at": now,
                "updated_at": now,
            }
            jobs.append(job)
            _save("script_generation_jobs.json", jobs)
            return _err("CONFLICT", "Failed to write script to disk", details=str(ex))

    job_id = _ulid_like()
    job = {
        "id": job_id,
        "client_id": client["id"],
        "request_id": _extra.get("request_id"),
        "tool_name": "generate_bigfix_action_script",
        "status": "succeeded",
        "timeout_seconds": eff_timeout,
        "template_id": None,
        "template_name": None,
        "description": description,
        "script_type": None,
        "include_logging": None,
        "include_error_handling": None,
        "logic_detection": None,
        "logic_remediation": None,
        "logic_relevance": None,
        "logic_action": action_logic,
        "parameters_object": None,
        "parameters_list": None,
        "requested_output_path": output_path,
        "requested_output_dir": None,
        "resolved_output_paths": resolved_paths,
        "generated_primary_content": primary,
        "generated_secondary_content": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    jobs.append(job)
    _save("script_generation_jobs.json", jobs)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "id": job_id,
        "status": job["status"],
        "timeout_seconds": eff_timeout,
        "output_path": output_path,
        "resolved_output_paths": resolved_paths,
        "script": primary,
        "latency_ms": latency_ms,
    }

def run_powershell_with_progress(code, timeout=60, ctx=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0046000" if __import__("os").path.isdir("./environment_mix/0046000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc_iso_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt_any(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo is None else s.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            try:
                return datetime.datetime.strptime(s, "%Y-%m-%dT%H:%M:%SZ")
            except Exception:
                return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)

        def b32(n, length):
            out = ""
            for _ in range(length):
                out = alphabet[n % 32] + out
                n //= 32
            return out

        rand = "".join(random.choice(alphabet) for _ in range(16))
        return f"{prefix}_{b32(ms,10)}{rand}"

    def _audit(endpoint, status_s, client_id=None, execution_id=None, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("psx_req"),
            "endpoint": endpoint,
            "status": status_s,
            "client_id": client_id,
            "execution_id": execution_id,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_utc_iso_z(),
        })
        _save("request_logs.json", logs)

    def _pick_client():
        clients = _load("clients.json")
        if not isinstance(clients, list):
            return None
        for c in clients:
            if not isinstance(c, dict):
                continue
            if c.get("status") != "active":
                continue
            dts = c.get("default_timeout_seconds")
            mts = c.get("max_timeout_seconds")
            rpm = c.get("requests_per_minute_limit")
            if not (isinstance(dts, int) and not isinstance(dts, bool)):
                continue
            if not (isinstance(mts, int) and not isinstance(mts, bool)):
                continue
            if not (isinstance(rpm, int) and not isinstance(rpm, bool) and rpm >= 1):
                continue
            if not (1 <= dts <= 300 and 1 <= mts <= 300 and dts <= mts):
                continue
            return c
        for c in clients:
            if isinstance(c, dict) and c.get("status") == "active":
                return c
        return None

    def _rate_limit_or_none(client):
        limit = client.get("requests_per_minute_limit")
        if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now_dt = datetime.datetime.utcnow()
        window_start = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client.get("id"):
                continue
            ts = _parse_dt_any(r.get("created_at"))
            if ts is None:
                continue
            if ts >= window_start:
                cnt += 1
        if cnt >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=limit)
        return None

    # validate
    if not isinstance(code, str) or not code.strip():
        _audit("run_powershell_with_progress", "error", None, None, "VALIDATION_ERROR", "code must be a non-empty string")
        return _err("VALIDATION_ERROR", "code must be a non-empty string")

    client = _pick_client()
    if not client:
        _audit("run_powershell_with_progress", "error", None, None, "UNAUTHORIZED", "No active client available")
        return _err("UNAUTHORIZED", "No active client available for this operation")

    rl = _rate_limit_or_none(client)
    if rl:
        _audit("run_powershell_with_progress", "error", client.get("id"), None, rl["error"]["code"], rl["error"]["message"])
        return rl

    # effective timeout
    if timeout is None:
        timeout_eff = client.get("default_timeout_seconds")
    else:
        timeout_eff = timeout
    if not isinstance(timeout_eff, int) or isinstance(timeout_eff, bool):
        _audit("run_powershell_with_progress", "error", client.get("id"), None, "VALIDATION_ERROR", "timeout must be an integer or null")
        return _err("VALIDATION_ERROR", "timeout must be an integer or null")
    timeout_eff = max(1, min(300, timeout_eff))
    max_t = client.get("max_timeout_seconds")
    if isinstance(max_t, int) and not isinstance(max_t, bool) and timeout_eff > max_t:
        timeout_eff = max_t

    executions = _load("powershell_executions.json")
    if not isinstance(executions, list):
        executions = []
    events = _load("execution_events.json")
    if not isinstance(events, list):
        events = []

    exec_id = _gen_id("psx_run")
    now = _now_utc_iso_z()

    # create execution succeeded (offline); still must emit at least one progress/log event
    row = {
        "id": exec_id,
        "client_id": client.get("id"),
        "request_id": getattr(ctx, "request_id", None) if ctx is not None else None,
        "tool_name": "run_powershell_with_progress",
        "timeout_seconds": timeout_eff,
        "code": code,
        "arguments": None,
        "status": "succeeded",
        "started_at": now,
        "finished_at": now,
        "duration_ms": 0,
        "exit_code": 0,
        "stdout": "",
        "stderr": "",
        "combined_output": "",
        "error_type": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    executions.append(row)
    _save("powershell_executions.json", executions)

    # sequence per execution: strictly increasing; this is new exec so start at 1
    evt_id = _gen_id("psx_evt")
    events.append({
        "id": evt_id,
        "execution_id": exec_id,
        "sequence": 1,
        "event_type": "progress",
        "level": None,
        "message": "Completed",
        "progress_current": 1,
        "progress_total": 1,
        "payload": None,
        "emitted_at": now,
        "created_at": now,
        "updated_at": now,
    })
    _save("execution_events.json", events)

    _audit("run_powershell_with_progress", "ok", client.get("id"), exec_id, None, None)
    return {"execution_id": exec_id, "output": row.get("combined_output") or ""}

def list_powershell_executions(client_id=None, request_id=None, status=None, tool_name=None, created_after=None, created_before=None, limit=50, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0046000" if __import__("os").path.isdir("./environment_mix/0046000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_request(client_id_for_log, endpoint, status_s, latency_ms, details=None):
        fname_candidates = ["request_logs.json", "api_requests.json", "usage_logs.json", "audit_logs.json"]
        for fn in fname_candidates:
            path = os.path.join(_DB, fn)
            if os.path.exists(path):
                rows = _load(fn)
                rid = "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=")
                row = {
                    "id": rid,
                    "client_id": client_id_for_log,
                    "endpoint": endpoint,
                    "status": status_s,
                    "latency_ms": int(latency_ms),
                    "created_at": now,
                    "details": details or {},
                }
                rows.append(row)
                _save(fn, rows)
                break

    def _resolve_active_client():
        clients = _load("clients.json")
        for c in clients:
            if c.get("status") == "active":
                return c
        return None

    def _parse_iso(s):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", "created_after/created_before must be ISO-8601 strings or null")
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1])
                return dt.replace(tzinfo=datetime.timezone.utc), None
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", "invalid ISO-8601 timestamp", value=s)

    def _decode_cursor(c):
        if c is None:
            return None, None
        if not isinstance(c, str) or not c:
            return None, _err("VALIDATION_ERROR", "cursor must be a string or null")
        try:
            raw = base64.urlsafe_b64decode(c.encode("ascii") + b"=" * (-len(c) % 4)).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict):
                return None, _err("VALIDATION_ERROR", "invalid cursor")
            return obj, None
        except (ValueError, json.JSONDecodeError):
            return None, _err("VALIDATION_ERROR", "invalid cursor encoding")

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    # Validate limit
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 200:
        _log_request(None, "list_powershell_executions", "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    # Validate status enum
    allowed_status = {"queued", "running", "succeeded", "failed", "timed_out", "cancelled"}
    if status is not None and status not in allowed_status:
        _log_request(None, "list_powershell_executions", "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "unknown status filter", allowed=sorted(list(allowed_status)))

    # Validate tool_name if present (must match known enum in schema)
    allowed_tools = {"run_powershell", "run_powershell_with_progress", "get_system_info", "get_running_services", "get_processes", "get_event_logs"}
    if tool_name is not None:
        if not isinstance(tool_name, str) or not tool_name:
            _log_request(None, "list_powershell_executions", "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "tool_name must be a string or null")
        if tool_name not in allowed_tools:
            _log_request(None, "list_powershell_executions", "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "unknown tool_name filter", allowed=sorted(list(allowed_tools)))

    # Validate ids
    if client_id is not None and (not isinstance(client_id, str) or not client_id):
        _log_request(None, "list_powershell_executions", "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "client_id must be a string when provided")
    if request_id is not None and (not isinstance(request_id, str) or request_id == ""):
        _log_request(None, "list_powershell_executions", "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "request_id must be a non-empty string or null")

    ca, e1 = _parse_iso(created_after)
    if e1:
        _log_request(None, "list_powershell_executions", "error", (time.time() - t0) * 1000, {"code": e1["error"]["code"]})
        return e1
    cb, e2 = _parse_iso(created_before)
    if e2:
        _log_request(None, "list_powershell_executions", "error", (time.time() - t0) * 1000, {"code": e2["error"]["code"]})
        return e2
    if ca and cb and ca > cb:
        _log_request(None, "list_powershell_executions", "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "created_after must be <= created_before")

    # Resolve ambient client if client_id omitted
    active_client = _resolve_active_client()
    if not active_client:
        _log_request(None, "list_powershell_executions", "error", (time.time() - t0) * 1000, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "no active client available for this request")
    effective_client_id = client_id or active_client.get("id")

    # Ensure client exists and is accessible (ambient)
    clients = _load("clients.json")
    client_row = None
    for c in clients:
        if c.get("id") == effective_client_id:
            client_row = c
            break
    if client_row is None:
        _log_request(active_client.get("id"), "list_powershell_executions", "error", (time.time() - t0) * 1000, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "client not found")

    # Cursor
    cur, cerr = _decode_cursor(cursor)
    if cerr:
        _log_request(effective_client_id, "list_powershell_executions", "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return cerr
    # Cursor carries last_seen_created_at + last_seen_id for stable pagination
    last_created_at = cur.get("last_created_at") if isinstance(cur, dict) else None
    last_id = cur.get("last_id") if isinstance(cur, dict) else None
    if cur is not None:
        if not isinstance(last_created_at, str) or not isinstance(last_id, str):
            _log_request(effective_client_id, "list_powershell_executions", "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "invalid cursor payload")

    executions = _load("powershell_executions.json")

    # Filter
    filtered = []
    for r in executions:
        if r.get("client_id") != effective_client_id:
            continue
        if request_id is not None and r.get("request_id") != request_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        r_ca = r.get("created_at")
        # created_at stored as ISO string with Z
        if (ca or cb) and isinstance(r_ca, str):
            dt_r, _ = _parse_iso(r_ca)
            if dt_r is not None:
                if ca and dt_r < ca:
                    continue
                if cb and dt_r > cb:
                    continue
        elif (ca or cb):
            continue
        filtered.append(r)

    # Sort newest-first by created_at then id
    def _sort_key(r):
        s = r.get("created_at") or ""
        return (s, r.get("id") or "")
    filtered.sort(key=_sort_key, reverse=True)

    # Apply cursor (exclusive)
    if cur is not None:
        new_filtered = []
        for r in filtered:
            if (r.get("created_at") or "") < last_created_at:
                new_filtered.append(r)
            elif (r.get("created_at") or "") == last_created_at and (r.get("id") or "") < last_id:
                new_filtered.append(r)
        filtered = new_filtered

    total = len(filtered)
    page = filtered[:limit]
    has_more = total > len(page)
    next_cursor = None
    if has_more and page:
        tail = page[-1]
        next_cursor = _encode_cursor({"last_created_at": tail.get("created_at"), "last_id": tail.get("id")})

    latency_ms = (time.time() - t0) * 1000
    _log_request(effective_client_id, "list_powershell_executions", "ok", latency_ms, {"returned": len(page)})

    return {
        "executions": page,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def get_powershell_execution(id, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0046000" if __import__("os").path.isdir("./environment_mix/0046000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc_iso_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)

        def b32(n, length):
            out = ""
            for _ in range(length):
                out = alphabet[n % 32] + out
                n //= 32
            return out

        rand = "".join(random.choice(alphabet) for _ in range(16))
        return f"{prefix}_{b32(ms,10)}{rand}"

    def _audit(status_s, client_id=None, execution_id=None, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _gen_id("psx_req"),
                "endpoint": "get_powershell_execution",
                "status": status_s,
                "client_id": client_id,
                "execution_id": execution_id,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_utc_iso_z(),
            }
        )
        _save("request_logs.json", logs)

    # Validate input
    if not isinstance(id, str) or not id.strip():
        _audit("error", None, None, "VALIDATION_ERROR", "id must be a non-empty string")
        return _err("VALIDATION_ERROR", "id must be a non-empty string", id=id)
    id = id.strip()

    execs = _load("powershell_executions.json")
    if not isinstance(execs, list):
        execs = []

    target = None
    for e in execs:
        if isinstance(e, dict) and e.get("id") == id:
            target = e
            break

    if not target:
        # Reads should not invent access-control failures: return NOT_FOUND for unknown id
        _audit("error", None, id, "NOT_FOUND", "powershell execution id does not exist")
        return _err("NOT_FOUND", "powershell execution id does not exist", id=id)

    # Ambient auth: choose a workable client context for logging (prefer the owning client if present and active)
    clients = _load("clients.json")
    if not isinstance(clients, list):
        clients = []

    client_id = target.get("client_id")
    client_row = None
    if isinstance(client_id, str):
        for c in clients:
            if isinstance(c, dict) and c.get("id") == client_id:
                client_row = c
                break

    # If owning client is missing/deleted/etc, still return the execution (no explicit auth parameter to restrict)
    # but we still log with the execution's client_id if present.
    _audit("ok", client_row.get("id") if isinstance(client_row, dict) else client_id, id, None, None)
    return {"execution": target}

def cancel_powershell_execution(id, reason=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0046000" if __import__("os").path.isdir("./environment_mix/0046000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc_iso_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt_any(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s.replace(tzinfo=None)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            dt = datetime.datetime.fromisoformat(s)
            if getattr(dt, "tzinfo", None) is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)

        def b32(n, length):
            out = ""
            for _ in range(length):
                out = alphabet[n % 32] + out
                n //= 32
            return out

        rand = "".join(random.choice(alphabet) for _ in range(16))
        return f"{prefix}_{b32(ms,10)}{rand}"

    def _audit(status_s, client_id=None, execution_id=None, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _gen_id("psx_req"),
                "endpoint": "cancel_powershell_execution",
                "status": status_s,
                "client_id": client_id,
                "execution_id": execution_id,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_utc_iso_z(),
            }
        )
        _save("request_logs.json", logs)

    # Validate input
    if not isinstance(id, str) or not id.strip():
        _audit("error", None, None, "VALIDATION_ERROR", "id must be a non-empty string")
        return _err("VALIDATION_ERROR", "id must be a non-empty string", id=id)
    id = id.strip()

    if reason is not None and not isinstance(reason, str):
        _audit("error", None, id, "VALIDATION_ERROR", "reason must be a string or null")
        return _err("VALIDATION_ERROR", "reason must be a string or null", id=id)

    execs = _load("powershell_executions.json")
    if not isinstance(execs, list):
        execs = []

    idx = None
    target = None
    for i, e in enumerate(execs):
        if isinstance(e, dict) and e.get("id") == id:
            idx = i
            target = e
            break

    if target is None:
        _audit("error", None, id, "NOT_FOUND", "powershell execution id does not exist")
        return _err("NOT_FOUND", "powershell execution id does not exist", id=id)

    # Resolve client context (for logging and to enforce client active requirement on mutations)
    clients = _load("clients.json")
    if not isinstance(clients, list):
        clients = []
    client_id = target.get("client_id")
    client_row = None
    if isinstance(client_id, str):
        for c in clients:
            if isinstance(c, dict) and c.get("id") == client_id:
                client_row = c
                break

    if not isinstance(client_row, dict):
        _audit("error", client_id if isinstance(client_id, str) else None, id, "UNAUTHORIZED", "no accessible client context for this execution")
        return _err("UNAUTHORIZED", "no accessible client context for this execution", id=id)

    if client_row.get("status") != "active":
        _audit("error", client_row.get("id"), id, "UNAUTHORIZED", "client.status must be 'active' to cancel executions")
        return _err("UNAUTHORIZED", "client.status must be 'active' to cancel executions", id=id, client_id=client_row.get("id"))

    # Enforce lifecycle transition rules
    current = target.get("status")
    if current not in ("queued", "running", "succeeded", "failed", "timed_out", "cancelled"):
        _audit("error", client_row.get("id"), id, "VALIDATION_ERROR", "invalid execution status in datastore")
        return _err("VALIDATION_ERROR", "invalid execution status in datastore", id=id, status=current)

    if current == "cancelled":
        # Idempotent: already cancelled; ensure metadata exists, but don't fabricate timestamps if already present
        _audit("ok", client_row.get("id"), id, None, None)
        return {"execution": target}

    if current in ("succeeded", "failed", "timed_out"):
        _audit("error", client_row.get("id"), id, "INVALID_TRANSITION", f"cannot cancel a terminal execution (status={current})")
        return _err("INVALID_TRANSITION", f"cannot cancel a terminal execution (status={current})", id=id, from_status=current, to_status="cancelled")

    # queued|running -> cancelled is allowed
    now_iso = _now_utc_iso_z()
    started_at = _parse_dt_any(target.get("started_at"))
    created_at = _parse_dt_any(target.get("created_at"))
    now_dt = _parse_dt_any(now_iso)

    # Apply state change
    target["status"] = "cancelled"
    target["updated_at"] = now_iso

    if current == "queued" and not target.get("started_at"):
        # Keep started_at null per schema expectation for never-started executions
        pass

    # Terminal state metadata
    if not target.get("finished_at"):
        target["finished_at"] = now_iso

    # duration_ms set when terminal
    base_dt = None
    if started_at is not None:
        base_dt = started_at
    elif created_at is not None:
        base_dt = created_at
    else:
        base_dt = now_dt
    if base_dt is not None and now_dt is not None:
        dur_ms = int(max(0, (now_dt - base_dt).total_seconds() * 1000))
        target["duration_ms"] = dur_ms
    else:
        target["duration_ms"] = target.get("duration_ms") if isinstance(target.get("duration_ms"), int) else 0

    # Success must have null error fields; cancelled is terminal but not "success". Populate error fields if empty.
    if reason is None or not reason.strip():
        cancel_msg = "Client cancelled request."
    else:
        cancel_msg = reason.strip()

    # Maintain existing more specific messages if present, but ensure it reflects cancellation
    target["error_type"] = "cancelled"
    target["error_message"] = cancel_msg
    if target.get("stderr") in (None, ""):
        target["stderr"] = cancel_msg

    # combined_output left as-is; stdout left as-is; exit_code left as-is

    execs[idx] = target
    _save("powershell_executions.json", execs)

    # Append an execution_event state_change (sequence strictly increasing)
    events = _load("execution_events.json")
    if not isinstance(events, list):
        events = []

    max_seq = 0
    for ev in events:
        if isinstance(ev, dict) and ev.get("execution_id") == id:
            s = ev.get("sequence")
            if isinstance(s, int) and s > max_seq:
                max_seq = s
    next_seq = max_seq + 1
    if next_seq < 1:
        next_seq = 1

    evt = {
        "id": _gen_id("psx_evt"),
        "execution_id": id,
        "sequence": next_seq,
        "event_type": "state_change",
        "level": None,
        "message": f"status {current} -> cancelled",
        "progress_current": None,
        "progress_total": None,
        "payload": {"from": current, "to": "cancelled", "reason": cancel_msg},
        "emitted_at": now_iso,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    events.append(evt)
    _save("execution_events.json", events)

    _audit("ok", client_row.get("id"), id, None, None)
    return {"execution": target, "event": evt}

def list_execution_events(execution_id, after_sequence=None, event_type=None, limit=100, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0046000" if __import__("os").path.isdir("./environment_mix/0046000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _audit(endpoint, status, client_id=None, credential_id=None, request_id=None, latency_ms=None, error_code=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            row = {
                "id": f"01{int(time.time()*1000):011d}{int(time.time_ns() % 10**20):020d}"[:26],
                "endpoint": endpoint,
                "status": status,
                "client_id": client_id,
                "credential_id": credential_id,
                "request_id": request_id,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "created_at": _now_iso(),
            }
            logs.append(row)
            _save("request_logs.json", logs)

    def _rate_limit_check(client_row):
        limitv = client_row.get("requests_per_minute_limit")
        if not isinstance(limitv, int) or limitv < 1:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if r.get("client_id") != client_row.get("id"):
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts is None:
                continue
            if ts >= window_start:
                cnt += 1
        if cnt >= limitv:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit=limitv, window_seconds=60)
        return None

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return _err("VALIDATION_ERROR", "Field 'cursor' must be a non-empty string or null.")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            return obj
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    t0 = time.time()
    endpoint = "list_execution_events"

    # Validate
    if not isinstance(execution_id, str) or not execution_id.strip():
        return _err("VALIDATION_ERROR", "Field 'execution_id' must be a non-empty string.")
    if after_sequence is not None:
        if not isinstance(after_sequence, int) or after_sequence < 0:
            return _err("VALIDATION_ERROR", "Field 'after_sequence' must be an integer >= 0 or null.")
    allowed_types = {"log", "progress", "output_chunk", "state_change"}
    if event_type is not None:
        if not isinstance(event_type, str) or event_type not in allowed_types:
            return _err("VALIDATION_ERROR", "Field 'event_type' must be one of: log, progress, output_chunk, state_change (or null).")
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "Field 'limit' must be an integer between 1 and 500.")

    # Resolve execution and client context
    executions = _load("powershell_executions.json")
    if not isinstance(executions, list):
        executions = []
    exec_row = None
    for r in executions:
        if r.get("id") == execution_id:
            exec_row = r
            break
    if exec_row is None:
        latency = int((time.time() - t0) * 1000)
        _audit(endpoint, "error", latency_ms=latency, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "PowerShell execution not found.", execution_id=execution_id)

    clients = _load("clients.json")
    if not isinstance(clients, list):
        clients = []
    client_row = None
    for c in clients:
        if c.get("id") == exec_row.get("client_id"):
            client_row = c
            break
    if client_row is None or client_row.get("status") == "deleted":
        latency = int((time.time() - t0) * 1000)
        _audit(endpoint, "error", client_id=exec_row.get("client_id"), latency_ms=latency, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized client context can serve this request.")

    rl_err = _rate_limit_check(client_row)
    if rl_err:
        latency = int((time.time() - t0) * 1000)
        _audit(endpoint, "error", client_id=client_row.get("id"), latency_ms=latency, error_code=rl_err["error"]["code"])
        return rl_err

    # Cursor handling
    cur_after = after_sequence
    cur_type = event_type
    if cursor is not None:
        decoded = _decode_cursor(cursor)
        if isinstance(decoded, dict) and "error" in decoded:
            latency = int((time.time() - t0) * 1000)
            _audit(endpoint, "error", client_id=client_row.get("id"), latency_ms=latency, error_code=decoded["error"]["code"])
            return decoded
        if decoded is None:
            pass
        else:
            # Expect cursor to bind to same execution_id and filters
            if decoded.get("execution_id") != execution_id:
                latency = int((time.time() - t0) * 1000)
                _audit(endpoint, "error", client_id=client_row.get("id"), latency_ms=latency, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Cursor does not match execution_id.")
            if decoded.get("event_type") != cur_type:
                latency = int((time.time() - t0) * 1000)
                _audit(endpoint, "error", client_id=client_row.get("id"), latency_ms=latency, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Cursor does not match event_type filter.")
            if decoded.get("after_sequence") is not None and not isinstance(decoded.get("after_sequence"), int):
                latency = int((time.time() - t0) * 1000)
                _audit(endpoint, "error", client_id=client_row.get("id"), latency_ms=latency, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            cur_after = decoded.get("after_sequence")

    events = _load("execution_events.json")
    if not isinstance(events, list):
        events = []

    filtered = []
    for ev in events:
        if ev.get("execution_id") != execution_id:
            continue
        seq = ev.get("sequence")
        if not isinstance(seq, int):
            continue
        if cur_after is not None and seq <= cur_after:
            continue
        if cur_type is not None and ev.get("event_type") != cur_type:
            continue
        filtered.append(ev)

    filtered.sort(key=lambda e: (e.get("sequence") if isinstance(e.get("sequence"), int) else 0, e.get("id") or ""))

    page = filtered[:limit]
    has_more = len(filtered) > len(page)
    next_cursor = None
    if page:
        last_seq = page[-1].get("sequence")
        if has_more and isinstance(last_seq, int):
            next_cursor = _encode_cursor({
                "execution_id": execution_id,
                "event_type": cur_type,
                "after_sequence": last_seq
            })

    latency = int((time.time() - t0) * 1000)
    _audit(endpoint, "ok", client_id=client_row.get("id"), latency_ms=latency)

    return {
        "events": page,
        "total": len(filtered),
        "has_more": has_more,
        "next_cursor": next_cursor
    }

def list_script_templates(template_name=None, status=None, limit=50, cursor=None, **_extra):
    import json, os, datetime, time, base64, random

