            return s if s.tzinfo is None else s.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            try:
                return datetime.datetime.strptime(s, "%Y-%m-%dT%H:%M:%SZ")
            except Exception:
                return None

    def _gen_req_id():
        return "psx_req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=")

    def _audit(endpoint, status_s, client_id=None, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_req_id(),
            "endpoint": endpoint,
            "status": status_s,
            "client_id": client_id,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_utc_iso_z(),
        })
        _save("request_logs.json", logs)

    # validate filters/pagination
    if template_name is not None and not isinstance(template_name, str):
        _audit("list_script_templates", "error", None, "VALIDATION_ERROR", "template_name must be a string or null")
        return _err("VALIDATION_ERROR", "template_name must be a string or null")
    if status is not None:
        if status not in ("active", "deprecated", "deleted"):
            _audit("list_script_templates", "error", None, "VALIDATION_ERROR", "status must be one of active, deprecated, deleted")
            return _err("VALIDATION_ERROR", "status must be one of active, deprecated, deleted")
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 200:
        _audit("list_script_templates", "error", None, "VALIDATION_ERROR", "limit must be an integer between 1 and 200")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        _audit("list_script_templates", "error", None, "VALIDATION_ERROR", "cursor must be a string or null")
        return _err("VALIDATION_ERROR", "cursor must be a string or null")

    # ambient auth: any active client (but listing not restricted by client in schema)
    clients = _load("clients.json")
    client_id = None
    if isinstance(clients, list):
        for c in clients:
            if isinstance(c, dict) and c.get("status") == "active":
                client_id = c.get("id")
                break

    # rate limit if possible
    if client_id is not None:
        client = None
        for c in clients:
            if isinstance(c, dict) and c.get("id") == client_id:
                client = c
                break
        if isinstance(client, dict):
            limitv = client.get("requests_per_minute_limit")
            if isinstance(limitv, int) and not isinstance(limitv, bool) and limitv >= 1:
                logs = _load("request_logs.json")
                if isinstance(logs, list):
                    now_dt = datetime.datetime.utcnow()
                    window_start = now_dt - datetime.timedelta(seconds=60)
                    cnt = 0
                    for r in logs:
                        if not isinstance(r, dict):
                            continue
                        if r.get("client_id") != client_id:
                            continue
                        ts = _parse_dt_any(r.get("created_at"))
                        if ts is None:
                            continue
                        if ts >= window_start:
                            cnt += 1
                    if cnt >= limitv:
                        _audit("list_script_templates", "error", client_id, "RATE_LIMIT", "Rate limit exceeded.")
                        return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=limitv)

    rows = _load("script_templates.json")
    if not isinstance(rows, list):
        rows = []

    # filter
    out = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if template_name is not None and r.get("template_name") != template_name:
            continue
        if status is not None and r.get("status") != status:
            continue
        out.append(r)

    # stable sort: template_name asc, version desc, id asc
    def _ver(x):
        v = x.get("version")
        return v if isinstance(v, int) and not isinstance(v, bool) else -1
    out.sort(key=lambda x: (str(x.get("template_name") or ""), -_ver(x), str(x.get("id") or "")))

    # pagination: cursor is base64 of integer offset
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("ascii") + b"===")
            start = int(raw.decode("utf-8"))
            if start < 0:
                raise ValueError("neg")
        except Exception:
            _audit("list_script_templates", "error", client_id, "VALIDATION_ERROR", "Invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    page = out[start:start + limit]
    next_cursor = None
    has_more = start + limit < len(out)
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(start + limit).encode("utf-8")).decode("ascii").rstrip("=")

    _audit("list_script_templates", "ok", client_id, None, None)
    return {
        "templates": page,
        "total": len(out),
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }
